#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.74-unified-live-search.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode("")))
for rel,spec in payload.items():
 p=root/rel; data=p.read_bytes()
 if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected 1.1.73 baseline: "+rel)
 lines=data.decode("utf-8").splitlines(keepends=True)
 for i1,i2,text in reversed(spec["ops"]): lines[i1:i2]=text.splitlines(keepends=True)
 p.write_text("".join(lines),encoding="utf-8")
# preservation lock: customer runtime must not change
customer=root/'assets'/'customer.js'
if hashlib.sha256(customer.read_bytes()).hexdigest()!="bc3d794decaae688ae97ae3a19ff520b9fc71cefa8c332f8aab0d7372818b5d4": raise SystemExit("customer.js preservation lock failed")
p=(root/'shishalove-app-bridge.php').read_text();m=(root/'assets'/'merchant.js').read_text();c=(root/'assets'/'bridge.css').read_text()
for token in ["Version: 1.1.74","merchant/search-index","slb_search_index_version_174","slb_visual_required_product_174","SLBF32\0","scheduleLiveTextSearch","Search product name, brand or SKU","slm-live-suggestions"]:
 if token not in p+m+c: raise SystemExit("missing required token: "+token)
for forbidden in ["Version: 1.1.73"]:
 if forbidden in p: raise SystemExit("stale version remains")
print("Bridge 1.1.74 unified Chrome-style live search patch applied")
